uid_t target_uid = 1001;
int status;

// Set fsuid (32-bit compatible)
// Used primarily for specific filesystem access checks (e.g., NFS server)
status = setfsuid32(target_uid);

if (status == -1) {
    // Error Handling: Check errno
    // Common Errors: EPERM, EINVAL
    if (errno == EINVAL) {
        // Kernel truncation error
        exit(EXIT_FAILURE);
    }
}

// Success: Filesystem permissions now based on target_uid
// EUID remains unchanged.
